import "./label.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type LabelProps = ComponentProps<"label">;

export function Label({ className, ...rest }: LabelProps) {
  return <label className={cx("ns-label", className)} {...rest} />;
}

@layer components {
  .ns-label {
    color: var(--text-heading, #111);
    font: inherit;
    line-height: var(--leading, 1.5625);
    cursor: default;
    user-select: none;
  }

  .ns-label[for] {
    cursor: pointer;
  }
}
